:root {
  --skel-bg: #e8e8ec;
  --skel-shine: #f4f4f6;
  --text: #111;
  --muted: #666;
  --card-border: #e0e0e4;
}

@media (prefers-color-scheme: dark) {
  :root {
    --skel-bg: #2a2a32;
    --skel-shine: #36363f;
    --text: #f4f4f5;
    --muted: #a1a1aa;
    --card-border: #3f3f46;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family:
    system-ui,
    -apple-system,
    'Segoe UI',
    Roboto,
    sans-serif;
  color: var(--text);
  background: var(--skel-shine);
}

.dashboard-shell {
  max-width: 56rem;
  margin: 0 auto;
  padding: 2rem 1.25rem 3rem;
}

.dashboard-shell h1 {
  margin: 0 0 1.5rem;
  font-size: 1.75rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.grid {
  display: grid;
}

.grid-cols-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.gap-4 {
  gap: 1rem;
}

.card,
.chart,
.invoices {
  padding: 1rem 1.125rem;
  border: 1px solid var(--card-border);
  border-radius: 10px;
  background: var(--skel-shine);
  margin-bottom: 1rem;
}

.card h2,
.chart h2,
.invoices h2 {
  margin: 0 0 0.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.card p {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
}

.chart ul,
.invoices ul {
  margin: 0;
  padding-left: 1.25rem;
}

.chart li,
.invoices li {
  margin: 0.35rem 0;
}

.dashboard-skeleton {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.skeleton-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.skeleton-card {
  padding: 1rem 1.125rem;
  border: 1px solid var(--card-border);
  border-radius: 10px;
  background: var(--skel-shine);
  min-height: 5.5rem;
}

.skeleton-section {
  padding: 1rem 1.125rem;
  border: 1px solid var(--card-border);
  border-radius: 10px;
  background: var(--skel-shine);
}

.skeleton-list {
  list-style: none;
  margin: 0.75rem 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.skeleton-line {
  height: 0.85rem;
  border-radius: 4px;
  background: linear-gradient(
    90deg,
    var(--skel-bg) 0%,
    var(--skel-shine) 50%,
    var(--skel-bg) 100%
  );
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.2s ease-in-out infinite;
}

.skeleton-line--short {
  width: 40%;
  margin-bottom: 0.65rem;
}

.skeleton-line--medium {
  width: 55%;
}

@keyframes skeleton-shimmer {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

.loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  min-height: 12rem;
  color: var(--muted);
}

.spinner {
  width: 2rem;
  height: 2rem;
  border: 3px solid var(--skel-bg);
  border-top-color: var(--muted);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

