  border-radius: 10px;
  background: var(--skel-shine);
  min-height: 5.5rem;
}

.skeleton-section {
  padding: 1rem 1.125rem;
  border: 1px solid var(--card-border);
  border-radius: 10px;
  background: var(--skel-shine);
}

.skeleton-list {
  list-style: none;
  margin: 0.75rem 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.skeleton-line {
  height: 0.85rem;
  border-radius: 4px;
  background: linear-gradient(
    90deg,
    var(--skel-bg) 0%,
    var(--skel-shine) 50%,
    var(--skel-bg) 100%
  );
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.2s ease-in-out infinite;
}

.skeleton-line--short {
  width: 40%;
  margin-bottom: 0.65rem;
}

.skeleton-line--medium {
  width: 55%;
}

@keyframes skeleton-shimmer {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

.loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  min-height: 12rem;
  color: var(--muted);
}

.spinner {
  width: 2rem;
  height: 2rem;
  border: 3px solid var(--skel-bg);
  border-top-color: var(--muted);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

